awk '
BEGIN { count = 0; sum = 0 }
# Skip header lines: lines starting with "Step" or "Loop time"
/^Step/ || /^Loop time/ { next }
# Check if the first column (Step) is an integer and greater than 15000
{
    step = $1;
    # Check if step is a valid number and greater than 15000
    if (step ~ /^[0-9]+$/ && step > 15000) {
        # The 4th column is Press
        press = $4;
        sum += press;
        count++;
    }
}
END {
    if (count > 0) {
        printf "%.8f %.8f\n", sum, count;
    } else {
        print "0 0";
    }
}
' run/log.lammps

awk '
BEGIN { count = 0; sum = 0 }
# Process line by line to find the specified range
{
    # The relevant lines are between the header line starting with "Step" and "Loop time"
    # Check if the line starts with a step number (and not just whitespace)
    if ($1 ~ /^[0-9]+$/) {
        step = $1;
        # Check for the condition: Step > 15000
        if (step > 15000) {
            press = $4;
            sum += press;
            count++;
        }
    }
}
END {
    if (count > 0) {
        # Calculate and print the mean, formatted to required precision
        mean = sum / count;
        printf "%.10f %.10f\n", mean, count;
    } else {
        print "0.0 0";
    }
}
' run/log.lammps

