    steps[NR] = $1;
    press[NR] = $5;
}
END {
    # Find the index corresponding to step 15000 or greater
    start_index = 0;
    for (i = 1; i <= NR; i++) {
        if (steps[i] > 15000) {
            start_index = i;
            break;
        }
    }

    if (start_index > 0) {
        sum_press = 0;
        count = 0;
        for (i = start_index; i <= NR; i++) {
            sum_press += press[i];
            count++;
        }
        mean_press = sum_press / count;
        printf "MEAN_PRESSURE %.6f\n", mean_press;
    } else {
        print "NO_DATA";
    }
}
